   278  static wchar_t *GetSsmlAttribute(wchar_t *pw, const char *name)
   279  {
   280          // Gets the value string for an attribute.
   281          // Returns NULL if the attribute is not present
   282
   283          int ix;
   284          static wchar_t empty[1] = { 0 };
   285
   286          while (*pw != 0) {
   287                  if (iswspace(pw[-1])) {
   288                          ix = 0;
   289                          while (*pw == name[ix]) {
   290                                  pw++;
   291                                  ix++;
   292                          }
   293                          if (name[ix] == 0) {
   294                                  // found the attribute, now get the value
   295                                  while (iswspace(*pw)) pw++;
   296                                  if (*pw == '=') pw++;
   297                                  while (iswspace(*pw)) pw++;
   298                                  if ((*pw == '"') || (*pw == '\'')) // allow single-quotes ?
   299                                          return pw+1;
   300                                  else
   301                                          return empty;
   302                          }
   303                  }
   304                  pw++;
   305          }
   306          return NULL;
   307  }
