   379  static void ProcessParamStack(char *outbuf, int *outix, int n_param_stack, PARAM_STACK *param_stack, int *speech_parameters)
   380  {
   381          // Set the speech parameters from the parameter stack
   382          int param;
   383          int ix;
   384          int value;
   385          char buf[20];
   386          int new_parameters[N_SPEECH_PARAM];
   387          static char cmd_letter[N_SPEECH_PARAM] = { 0, 'S', 'A', 'P', 'R', 0, 'C', 0, 0, 0, 0, 0, 'F' }; // embedded command letters
   388
   389          for (param = 0; param < N_SPEECH_PARAM; param++)
   390                  new_parameters[param] = -1;
   391
   392          for (ix = 0; ix < n_param_stack; ix++) {
   393                  for (param = 0; param < N_SPEECH_PARAM; param++) {
   394                          if (param_stack[ix].parameter[param] >= 0)
   395                                  new_parameters[param] = param_stack[ix].parameter[param];
   396                  }
   397          }
   398
   399          for (param = 0; param < N_SPEECH_PARAM; param++) {
   400                  if ((value = new_parameters[param]) != speech_parameters[param]) {
   401                          buf[0] = 0;
   402
   403                          switch (param)
   404                          {
   405                          case espeakPUNCTUATION:
   406                                  option_punctuation = value-1;
   407                                  break;
   408                          case espeakCAPITALS:
   409                                  option_capitals = value;
   410                                  break;
   411                          case espeakRATE:
   412                          case espeakVOLUME:
   413                          case espeakPITCH:
   414                          case espeakRANGE:
   415                          case espeakEMPHASIS:
   416                                  sprintf(buf, "%c%d%c", CTRL_EMBEDDED, value, cmd_letter[param]);
   417                                  break;
   418                          }
   419
   420                          speech_parameters[param] = new_parameters[param];
   421                          strcpy(&outbuf[*outix], buf);
   422                          *outix += strlen(buf);
   423                  }
   424          }
   425  }
