   427  static PARAM_STACK *PushParamStack(int tag_type, int *n_param_stack, PARAM_STACK *param_stack)
   428  {
   429          int ix;
   430          PARAM_STACK *sp;
   431
   432          sp = &param_stack[*n_param_stack];
   433          if (*n_param_stack < (N_PARAM_STACK-1))
   434                  (*n_param_stack)++;
   435
   436          sp->type = tag_type;
   437          for (ix = 0; ix < N_SPEECH_PARAM; ix++)
   438                  sp->parameter[ix] = -1;
   439          return sp;
   440  }
   441
   442  static void PopParamStack(int tag_type, char *outbuf, int *outix, int *n_param_stack, PARAM_STACK *param_stack, int *speech_parameters)
   443  {
   444          // unwind the stack up to and including the previous tag of this type
   445          int ix;
   446          int top = 0;
   447
   448          if (tag_type >= SSML_CLOSE)
   449                  tag_type -= SSML_CLOSE;
   450
   451          for (ix = 0; ix < *n_param_stack; ix++) {
   452                  if (param_stack[ix].type == tag_type)
   453                          top = ix;
   454          }
   455          if (top > 0)
   456                  *n_param_stack = top;
   457          ProcessParamStack(outbuf, outix, *n_param_stack, param_stack, speech_parameters);
   458  }
